function validate([cpdomains]) {
  if (!Array.isArray(cpdomains) || cpdomains.length < 1 || cpdomains.length > 100) return 'cpdomains needs 1 to 100 entries.';
  for (const entry of cpdomains) {
    if (typeof entry !== 'string' || entry.length < 1 || entry.length > 100) return 'Each entry is 1 to 100 characters long.';
    const match = /^([1-9][0-9]*) [a-z]+\.[a-z]+(\.[a-z]+)?$/.exec(entry);
    if (!match) return 'Each entry looks like "rep d1.d2" or "rep d1.d2.d3" with lowercase labels.';
    if (Number(match[1]) > 10000) return 'Each visit count is between 1 and 10000.';
  }
  return null;
}

