function subdomainVisits(cpdomains) {
  const counts = new Map();
  for (const entry of cpdomains) {
    const space = entry.indexOf(' ');
    const visits = Number(entry.slice(0, space));
    const domain = entry.slice(space + 1);
    counts.set(domain, (counts.get(domain) ?? 0) + visits);
    for (let i = 0; i < domain.length; i++) {
      if (domain[i] === '.') {
        const parent = domain.slice(i + 1);
        counts.set(parent, (counts.get(parent) ?? 0) + visits);
      }
    }
  }
  const result = [];
  for (const [domain, total] of counts) {
    result.push(total + ' ' + domain);
  }
  return result;
}

