function subdomainVisits(cpdomains) {
  const names = [];
  const totals = [];
  for (const entry of cpdomains) {
    const [rep, full] = entry.split(' ');
    const labels = full.split('.');
    for (let k = 0; k < labels.length; k++) {
      const name = labels.slice(k).join('.');
      let at = names.indexOf(name);
      if (at < 0) { names.push(name); totals.push(0); at = names.length - 1; }
      totals[at] += parseInt(rep, 10);
    }
  }
  return names.map((name, i) => `${totals[i]} ${name}`);
}

