function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  const word = (max) => {
    const length = 1 + Math.floor(rand() * max);
    let text = '';
    for (let i = 0; i < length; i++) text += String.fromCharCode(97 + Math.floor(rand() * (size === 'large' ? 26 : 3)));
    return text;
  };
  const large = size === 'large';
  const tops = Array.from({ length: large ? 6 : 2 }, () => word(3));
  const mids = Array.from({ length: large ? 30 : 3 }, () => word(large ? 12 : 3));
  const n = large ? 100 : 1 + Math.floor(rand() * 6);
  const cpdomains = [];
  for (let i = 0; i < n; i++) {
    const rep = rand() < 0.15 ? (rand() < 0.5 ? 1 : 10000) : 1 + Math.floor(rand() * (large ? 10000 : 50));
    let domain = pick(mids) + '.' + pick(tops);
    if (rand() < 0.6) domain = word(large ? 20 : 3) + '.' + domain;
    cpdomains.push(rep + ' ' + domain);
  }
  return [cpdomains];
}
